#!/usr/bin/env python3
"""simcompare 단일 파일 실행기 (자동 생성: scripts/build_single_file.py). 소스 해시 87b00e5903fb7c9e1aeab846244ea3a61c90879ccbe59242abb968c893ee56e4.
서버 wrapper가 명령줄 인자를 넘기지 못할 때 쓴다. 아래 EDIT 블록만 고치고 이 파일을 그대로 실행한다."""
# 0b회차(선택, 0회차 뒤): 전압·임피던스를 채운 dv_sheet.csv로 전극쌍별 ΔV, 최대 타이밍, 등급(None/Low/High)을 계산한다.
# PNG·CSV 내용은 열지 않고 case 폴더 이름에서 short 쌍을 모은다(open과 같은 이름 쌍은 빼고 manifest에 기록).
# --product-id는 필수이며 기본값이 없다. --low-low-threshold-v는 선택이다(없으면 low–low 쌍도 ΔV>0이면 High).
# 시트 오류는 행 번호와 함께 모두 한 번에 보여 주고 종료 코드 2로 멈춘다(출력 없음). Excel에서는 'CSV UTF-8'로 저장한다.
# --out은 아직 없는 새 경로여야 한다. 상세는 docs/dv_grade.md.
# ============================== EDIT BELOW: 이 블록만 고치세요 ==============================
# 각 작업은 `python -m simcompare <명령> <인자...>`와 같다. 명령 이름은 import-hotspots, validate-data, compare,
# electrode-map, import-electrode-assets, export-review-rois, candidates-change, candidates, confirm-pairs, compare-windows, report 등이다.
# 인자는 명령줄에서 쓰던 그대로 문자열 리스트로 적는다. 상대 경로는 BASE_DIR 기준이다(아래). wrapper가 이 파일을 다른 곳에
# 복사해 실행하면 "이 .py가 있는 폴더"가 달라지므로, 상대 경로를 쓸 때는 BASE_DIR를 절대 경로로 적는 것이 안전하다.
# 작업은 위에서부터 차례로 실행된다. 종료 코드 0(완료)과 3(부분 결과)은 다음 작업으로 넘어가고, 그 밖의 코드는 멈춘다.
JOBS = [
    # reference (QA4_R00). 제품마다 한 번 실행한다. 예시 — 제품에 맞게 바꾼다: 경계 3 V는 예시값. 경계를 쓰지 않으면 --low-low-threshold-v 와 값을 지운다
    ('dv-grade', [
        '--sheet', 'data/dv_template/QA4_R00/dv_sheet.csv',
        '--root', 'data/input/hotspot/QA4_R00',
        '--product-id', 'QA4_R00',
        '--low-low-threshold-v', '3',
        '--out', 'data/dv_grade/QA4_R00',
    ]),
    # target (QA4_T00). 제품마다 한 번 실행한다(4b회차는 두 제품의 dv-grade 출력 폴더를 모두 읽는다)
    ('dv-grade', [
        '--sheet', 'data/dv_template/QA4_T00/dv_sheet.csv',
        '--root', 'data/input/hotspot/QA4_T00',
        '--product-id', 'QA4_T00',
        '--low-low-threshold-v', '3',
        '--out', 'data/dv_grade/QA4_T00',
    ]),
]
LOG_FILE = 'runs/simcompare_0b_dv_grade.log'   # stdout/stderr를 이 파일에도 남긴다. 필요 없으면 None
WORK_DIR = None                               # 패키지를 풀 폴더. None이면 이 파일 옆, 쓸 수 없으면 임시 폴더
BASE_DIR = None                               # JOBS·LOG_FILE·WORK_DIR의 상대 경로 기준 폴더(절대 경로). None이면 이 .py가 있는 폴더
